import { sdkFetch } from '../client'

export interface SubscribeToNewsletterData {
	email: string
	name?: string
}

export interface SubscribeToNewsletterResult {
	ok: boolean
	error?: string
}

/**
 * Subscribe an email to the tenant newsletter (single opt-in). Idempotent —
 * re-subscribing an unsubscribed address flips it back to subscribed and the
 * response never reveals whether the address already existed.
 */
export async function subscribeToNewsletter(
	data: SubscribeToNewsletterData,
): Promise<SubscribeToNewsletterResult> {
	const res = await sdkFetch<{ ok: boolean; subscribed?: boolean }>(
		'/newsletter?action=subscribe',
		{
			method: 'POST',
			body: JSON.stringify(data),
		},
	)
	return res.error ? { ok: false, error: res.error } : { ok: res.data.ok }
}

export interface UnsubscribeFromNewsletterData {
	email: string
}

export interface UnsubscribeFromNewsletterResult {
	ok: boolean
	error?: string
}

/**
 * Remove an email from the tenant newsletter. Takes effect immediately.
 *
 * Idempotent, and successful for an address that was never on the list — the
 * result deliberately does not say which, so this can't be used to check
 * whether someone is a subscriber. Show a neutral confirmation ("if that
 * address was on the list, it has been removed"), never "you were not found".
 */
export async function unsubscribeFromNewsletter(
	data: UnsubscribeFromNewsletterData,
): Promise<UnsubscribeFromNewsletterResult> {
	const res = await sdkFetch<{ ok: boolean; unsubscribed?: boolean }>(
		'/newsletter?action=unsubscribe',
		{
			method: 'POST',
			body: JSON.stringify(data),
		},
	)
	return res.error ? { ok: false, error: res.error } : { ok: res.data.ok }
}
