'use client'

import { useState } from 'react'
import { unsubscribeFromNewsletter } from '../../hooks/useNewsletter'

export interface NewsletterUnsubscribeProps {
	title?: string | undefined
	description?: string | undefined
	buttonLabel?: string | undefined
	placeholder?: string | undefined
	/**
	 * Shown after a successful submit. Keep it neutral — it must read the same
	 * whether or not the address was on the list, so the page can't be used to
	 * check whether someone is a subscriber.
	 */
	successMessage?: string | undefined
	/** Optional line under the success message, e.g. "Changed your mind?". */
	successHint?: string | undefined
	className?: string | undefined
	onSuccess?: ((email: string) => void) | undefined
}

/**
 * Self-serve newsletter unsubscribe. The tokenized one-click link inside each
 * issue is still the primary path; this is for people who deleted the email,
 * never received one (an imported address), or just want off the list now.
 */
export function NewsletterUnsubscribe({
	title = 'Unsubscribe',
	description = 'Enter the email address you want removed from our newsletter.',
	buttonLabel = 'Unsubscribe',
	placeholder = 'you@example.com',
	successMessage = 'If that address was on our list, it has been removed.',
	successHint,
	className,
	onSuccess,
}: NewsletterUnsubscribeProps) {
	const [email, setEmail] = useState('')
	const [submitting, setSubmitting] = useState(false)
	const [done, setDone] = useState(false)
	const [error, setError] = useState('')

	async function handleSubmit(e: React.FormEvent) {
		e.preventDefault()
		setError('')
		setSubmitting(true)

		try {
			const result = await unsubscribeFromNewsletter({ email })
			if (!result.ok) {
				setError(result.error ?? 'Something went wrong. Please try again.')
				return
			}
			setDone(true)
			onSuccess?.(email)
		} catch {
			setError('Failed to unsubscribe. Please try again.')
		} finally {
			setSubmitting(false)
		}
	}

	if (done) {
		return (
			<div className={`rounded-xl border bg-base-100 p-6 text-center ${className ?? ''}`.trim()}>
				<div className="mx-auto mb-3 flex h-10 w-10 items-center justify-center rounded-full bg-success/20">
					<svg className="h-5 w-5 text-success" fill="none" viewBox="0 0 24 24" stroke="currentColor">
						<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
					</svg>
				</div>
				<p className="font-semibold">{successMessage}</p>
				{successHint && <p className="mt-1 text-sm text-base-content/60">{successHint}</p>}
			</div>
		)
	}

	return (
		<div className={`rounded-xl border bg-base-100 p-6 ${className ?? ''}`.trim()}>
			{title && <h2 className="text-xl font-semibold">{title}</h2>}
			{description && <p className="mt-1 text-base-content/60">{description}</p>}

			<form onSubmit={handleSubmit} className="mt-4 space-y-3">
				<input
					type="email"
					required
					value={email}
					onChange={(e) => setEmail(e.target.value)}
					placeholder={placeholder}
					aria-label="Email address"
					className="input input-bordered w-full"
				/>

				{error && <p className="text-sm text-error">{error}</p>}

				<button type="submit" disabled={submitting} className="btn btn-primary w-full">
					{submitting ? 'Removing...' : buttonLabel}
				</button>
			</form>
		</div>
	)
}
